<?php
namespace App\Http\Controllers;use App\Models\CustomerVehicleSale;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;class SalesAdjustmentController{public function create(){return view('sales-adjustments.create',['sales'=>CustomerVehicleSale::latest()->get(['id','sale_no','customer_id','segment_id','dealer']),'segments'=>DB::table('crm_segments')->where('is_active',true)->get()]);}public function store(Request $r){$d=$r->validate(['customer_vehicle_sale_id'=>['nullable','exists:customer_vehicle_sales,id'],'segment_id'=>['nullable','exists:crm_segments,id'],'adjustment_type'=>['required','in:discount,charge,correction'],'amount'=>['required','numeric','min:0'],'adjustment_date'=>['required','date'],'remarks'=>['nullable','string']]);DB::table('sales_adjustments')->insert($d+['reference_no'=>'SAD-'.now()->format('ymdHis'),'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('sales-adjustments.create')->with('success','Sales adjustment saved.');}}
